 function unpack(data,courses,current={}){if(!record(data)||![1,2].includes(data.schemaVersion))throw Error('Unsupported practice format.');const source=data.schemaVersion===1?data.notes:data.courses;if(!record(source))throw Error('The file has no valid practice records.');const out=structuredClone(current);let skipped=0;for(const c of courses){const n=source[c.id];if(!record(n))continue;if(data.schemaVersion===2&&n.version!==(c.version||1)){skipped++;continue;}const prev=record(out[c.id])?out[c.id]:{};const activities={...(record(prev.activities)?prev.activities:{})};for(const [i,a] of c.activities.entries()){const k=data.schemaVersion===1?String(i):activityId(a,i);if(n.activities?.[k]===true)activities[i]=true;}const supports=[...new Set([...(Array.isArray(prev.supports)?prev.supports:[]),...(Array.isArray(n.supports)?n.supports:[])].filter(v=>Number.isInteger(v)&&v>=0&&v<5))];out[c.id]={...prev,activities,supports,offline:prev.offline===true||n.offline===true};}return{notes:out,skipped};}
 function matches(a,f){const text=[a.title,a.summary,a.population,a.journalTitle,...(a.tags||[])].join(' ').toLowerCase();if(f.q&&!text.includes(f.q.toLowerCase()))return false;if(f.topic&&!(a.tags||[]).includes(f.topic))return false;if(f.review&&a.reviewScope!==f.review)return false;if(f.design&&!String(a.studyDesign||'').toLowerCase().includes(f.design))return false;if(f.year&&String(a.year)!==f.year)return false;if(f.language&&(a.language||'unknown')!==f.language)return false;if(f.access&&(a.accessStatus||'unknown')!==f.access)return false;if(f.age&&!(a.ageGroups||['unknown']).includes(f.age))return false;return true;}
